#!/usr/bin/env node
// Claude Code Stop hook — generated by KeelWright.
// When Claude finishes a turn that changed files, runs `npm run check` (lint, format check, type
// check, unit tests, theme drift). If it fails, Claude is told why and continues to fix it
// (exit 2). It runs at most once per stop: when Claude is already continuing because of this
// hook, it lets it stop.

import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

let input = {};
try {
  input = JSON.parse(readFileSync(0, 'utf8'));
} catch {
  // no input: treat as a normal stop
}
if (input.stop_hook_active) process.exit(0);

const root = process.env.CLAUDE_PROJECT_DIR ?? input.cwd ?? process.cwd();
if (!existsSync(join(root, 'node_modules'))) process.exit(0);

const status = spawnSync('git', ['status', '--porcelain'], { cwd: root, encoding: 'utf8' });
if (status.status !== 0 || !status.stdout.trim()) process.exit(0); // not a repo, or nothing changed

const r = spawnSync('npm', ['run', 'check', '--silent'], { cwd: root, encoding: 'utf8', timeout: 5 * 60_000 });
if (r.status !== 0) {
  const output = `${r.stdout ?? ''}\n${r.stderr ?? ''}`.trim().split('\n').slice(-40).join('\n');
  process.stderr.write(`npm run check fails after these changes. Fix the cause (don't weaken or skip checks):\n${output}\n`);
  process.exit(2);
}
process.exit(0);
